  margin-bottom: 1.5rem;
  align-items: center;
  flex-wrap: wrap;
}

:scope .control-label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--ink);
  margin-right: 0.5rem;
}

:scope .control-input {
  padding: 0.5rem;
  border: 1px solid var(--line);
  border-radius: 4px;
  font-size: 0.875rem;
  background: #fff;
  color: var(--ink);
}

:scope .btn-reset {
  background: var(--accent);
