  box-shadow: 0 4px 6px rgba(0,0,0,0.1);
}

:scope .chart-tooltip.visible {
  opacity: 1;
}

:scope .data-panel {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 1.25rem;
}

:scope .panel-title {
  font-size: 1rem;
  font-weight: 600;
  color: var(--accent);
  margin: 0 0 1rem 0;
  border-bottom: 1px solid var(--line);
  padding-bottom: 0.5rem;
}

:scope .detail-content {
  font-size: 0.9375rem;
  color: var(--ink);
  min-height: 80px;
}

